import { promises as fs } from "fs";
import path from "path";

export type Book = {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: "reading" | "finished";
  createdAt: string;
  finishedAt: string | null;
};

const DATA_DIR = path.join(process.cwd(), "data");
const DATA_FILE = path.join(DATA_DIR, "books.json");

async function readAll(): Promise<Book[]> {
  try {
    const raw = await fs.readFile(DATA_FILE, "utf8");
    return JSON.parse(raw) as Book[];
  } catch (err: unknown) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw err;
  }
}

async function writeAll(books: Book[]): Promise<void> {
  await fs.mkdir(DATA_DIR, { recursive: true });
  const tmp = DATA_FILE + ".tmp";
  await fs.writeFile(tmp, JSON.stringify(books, null, 2) + "\n", "utf8");
  await fs.rename(tmp, DATA_FILE);
}

export async function getBooks(): Promise<Book[]> {
  const books = await readAll();
  return books.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

export async function getBook(id: string): Promise<Book | null> {
  const books = await readAll();
  return books.find((b) => b.id === id) ?? null;
}

export async function addBook(input: {
  title: string;
  author: string;
  notes?: string;
}): Promise<Book> {
  const books = await readAll();
  const book: Book = {
    id: crypto.randomUUID(),
    title: input.title,
    author: input.author,
    notes: input.notes ?? "",
    status: "reading",
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await writeAll(books);
  return book;
}

export async function markFinished(id: string): Promise<Book | null> {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = "finished";
  book.finishedAt = new Date().toISOString();
  await writeAll(books);
  return book;
}

export async function updateNotes(
  id: string,
  notes: string,
): Promise<Book | null> {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.notes = notes;
  await writeAll(books);
  return book;
}

