import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { addBook, markFinished, updateNotes } from "@/lib/books";

export async function addBookAction(formData: FormData) {
  const title = String(formData.get("title") ?? "").trim();
  const author = String(formData.get("author") ?? "").trim();
  const notes = String(formData.get("notes") ?? "").trim();
  if (!title || !author) return;
  const book = await addBook({ title, author, notes });
  revalidatePath("/");
  redirect(`/books/${book.id}`);
}

export async function markFinishedAction(formData: FormData) {
  const id = String(formData.get("id") ?? "");
  if (!id) return;
  await markFinished(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

export async function updateNotesAction(formData: FormData) {
  const id = String(formData.get("id") ?? "");
  const notes = String(formData.get("notes") ?? "");
  if (!id) return;
  await updateNotes(id, notes);
  revalidatePath(`/books/${id}`);
}

