import Link from "next/link";
import { getBooks, type Book } from "@/lib/books";
import { addBookAction, markFinishedAction } from "./actions";

export const dynamic = "force-dynamic";

function BookRow({ book }: { book: Book }) {
  return (
    <li className="book-row">
      <Link href={`/books/${book.id}`} className="book-link">
        <span className="book-title">{book.title}</span>
        <span className="book-author">{book.author}</span>
      </Link>
      {book.status === "reading" && (
        <form action={markFinishedAction}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit">Mark finished</button>
        </form>
      )}
      {book.status === "finished" && book.finishedAt && (
        <span className="finished-date">
          Finished {new Date(book.finishedAt).toLocaleDateString()}
        </span>
      )}
    </li>
  );
}

export default async function Home() {
  const books = await getBooks();
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");

  return (
    <>
      <section>
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="empty">Nothing on the go.</p>
        ) : (
          <ul className="book-list">
            {reading.map((b) => (
              <BookRow key={b.id} book={b} />
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Add a book</h2>
        <form action={addBookAction} className="add-form">
          <label>
            Title
            <input name="title" required />
          </label>
          <label>
            Author
            <input name="author" required />
          </label>
          <label>
            Notes (optional)
            <textarea name="notes" rows={3} />
          </label>
          <button type="submit">Add book</button>
        </form>
      </section>

      <section>
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="empty">Nothing finished yet.</p>
        ) : (
          <ul className="book-list">
            {finished.map((b) => (
              <BookRow key={b.id} book={b} />
            ))}
          </ul>
        )}
      </section>
    </>
  );
}

