import { notFound } from "next/navigation";
import { getBook } from "@/lib/books";
import { markFinishedAction, updateNotesAction } from "../../actions";

export const dynamic = "force-dynamic";

export default async function BookPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  return (
    <article>
      <p>
        <Link href="/">&larr; All books</Link>
      </p>
      <h1>{book.title}</h1>
      <p className="book-author">by {book.author}</p>
      <p className="status">
        {book.status === "reading"
          ? "Currently reading"
          : `Finished ${
              book.finishedAt
                ? new Date(book.finishedAt).toLocaleDateString()
                : ""
            }`}
      </p>

      {book.status === "reading" && (
        <form action={markFinishedAction}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit">Mark finished</button>
        </form>
      )}

      <h2>Notes</h2>
      <form action={updateNotesAction} className="notes-form">
        <input type="hidden" name="id" value={book.id} />
        <textarea name="notes" rows={6} defaultValue={book.notes} />
        <button type="submit">Save notes</button>
      </form>
    </article>
  );
}

